INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(117732, 'ruRU', '', 'На цели максимум Загнивающих ран. Используй Удар Бича!', 24330),
(117733, 'ruRU', '', 'Использование Удара Бича после Загнивающего удара — мощная комбинация!', 24330),
(117734, 'ruRU', '', 'Используй Удар Бича!', 24330),
(117735, 'ruRU', '', 'Твой прислужник мёртв. Используй Поднятие мертвых, чтобы призвать нового прислужника.', 24330),
(117736, 'ruRU', '', 'Смертельная чума спала с цели. Используй Вспышку прямо сейчас!', 24330),
(117737, 'ruRU', '', 'Используй Вспышку!', 24330),
(117738, 'ruRU', '', 'Вспышка спала с цели, используй её сейчас!', 24330),
(117739, 'ruRU', '', 'Используй Загнивающий удар!', 24330),
(117740, 'ruRU', '', 'На цели нет Загнивающих ран. Используй Загнивающий удар прямо сейчас!', 24330),
(117741, 'ruRU', '', 'Используй Удар смерти!', 24330),
(117742, 'ruRU', '', 'Используй Оковы смерти!', 24330),
(117743, 'ruRU', '', 'Оковы смерти бесплатны! Используй их сейчас!', 24330),
(117746, 'ruRU', '', 'Используй Армию мертвых!', 24330),
(117747, 'ruRU', '', 'Отлично сделано, $p! Теперь ты готов сражаться как рыцарь смерти осквернения.', 24330),
(117748, 'ruRU', '', 'Покажи мне, что ты овладел силами тьмы!', 24330),
(117749, 'ruRU', '', 'Используй Удар смерти по цели, чтобы восстановить часть своего здоровья.', 24330),
(117750, 'ruRU', '', 'Его тёмная сила наносит урон твоему врагу и восстанавливает часть твоего здоровья.', 24330),
(117751, 'ruRU', '', 'Когда получаешь чрезмерный урон в бою, Удар смерти может помочь уравнять шансы.', 24330),
(117757, 'ruRU', '', 'Твои атаки иногда позволяют использовать Оковы смерти без затрат силы рун. Воспользуйся этим, когда сможешь.', 24330),
(117758, 'ruRU', '', 'Используй Оковы смерти на тренировочном манекене.', 24330),
(117759, 'ruRU', '', 'Твои атаки накапливают силу рун, которую можно использовать для применения Оков смерти — заклинания, что обрушивает на цель всплеск тёмной энергии и восстанавливает энергию твоему вурдалаку-прислужнику.', 24330),
(117760, 'ruRU', '', 'Старайся использовать Удар Бича только тогда, когда цель поражена Загнивающими ранами.', 24330),
(117761, 'ruRU', '', 'Используй Удар Бича на тренировочном манекене после того, как он заражён Загнивающим ударом.', 24330),
(117762, 'ruRU', '', 'Загнивающий удар, за которым следует Удар Бича — это комбинация ударов, которую выдержат немногие враги.', 24330),
(117763, 'ruRU', '', 'Ох, похоже, это больно! После заражения цели Загнивающим ударом ты готов вскрыть вызванные тобой язвы, используя Удар Бича!', 24330),
(117764, 'ruRU', '', 'Используй Загнивающий удар на тренировочном манекене.', 24330),
(117765, 'ruRU', '', 'Загнивающий удар наносит урон и накладывает Загнивающие раны на твою цель.', 24330),
(117766, 'ruRU', '', 'Теперь, когда твой враг шатается от миазмов чумы, пора нанести удар вблизи.', 24330),
(117767, 'ruRU', '', 'Используй Вспышку на тренировочном манекене.', 24330),
(117769, 'ruRU', '', 'Вспышка наносит урон со временем и высвобождает Смертельную чуму, что распространяется на находящихся рядом врагов.', 24330),
(117770, 'ruRU', '', 'Лучший способ начать бой — заразить врага множеством болезней на расстоянии.', 24330),
(117771, 'ruRU', '', 'Используй Поднятие мертвых, чтобы призвать своего прислужника.', 24330),
(117772, 'ruRU', '', 'Тебе следует всегда стараться иметь прислужника при себе.', 24330),
(117773, 'ruRU', '', 'Но твой величайший союзник — сама смерть. Поднятие мертвых оживит труп, чтобы он служил твоим вурдалачьим прислужником.', 24330),
(117774, 'ruRU', '', 'Болезни изматывают твоего врага, пока твои мощные атаки в ближнем бою добивают его.', 24330),
(117775, 'ruRU', '', 'Будучи рыцарем смерти осквернения, ты повелеваешь силами болезни и смерти.', 24330),
(117840, 'ruRU', '', 'Используй Притворную смерть, чтобы заставить моего солдата прекратить атаку.', 24330),
(117841, 'ruRU', '', 'Когда поражение неминуемо, используй Притворную смерть, чтобы обмануть врагов и заставить их думать, что ты больше не угроза.', 24330),
(117842, 'ruRU', '', 'Даже величайшие искатели приключений иногда оказываются не в силах справиться с ситуацией.', 24330),
(117843, 'ruRU', '', 'Используй Залп, чтобы расправиться со всеми врагами.', 24330);
